Trigger.script:
local list = { ["Eleusis"] = "Primordial Empire of Nature", ["Ashtan"] = "Dread Nation of Ashtan" }
-- Capture the current city local my_city = city_capture() local city_title = list[my_city]
-- Check if matches[2] starts with the header we want to skip -- We use :find() to be more flexible than an exact == match if city_title and matches[2]:find("Enemies of the " .. city_title) then return else local enemies = matches[2]:split(", ") for _, enemy in ipairs(enemies) do -- Clean up the name (remove any trailing periods or spaces) enemy = enemy:gsub("%.", ""):trim()
if enemy ~= "" and not table.contains(NDB.cityEnemies, enemy) then table.insert(NDB.cityEnemies, enemy)
if not NDB_Exists(enemy) then NDB_Acquire(enemy) end end end
-- Sort ONCE after the loop is done table.sort(NDB.cityEnemies) end setTriggerStayOpen("city enemies", 0) saveTableToJSON(NDB.cityEnemies, "cityenemylist")

if matches[2] == "The following are ACTIVE citizens of " .. city_capture() then return else local allies = matches[2]:split(", ") for _, ally in ipairs(allies) do table.insert(NDB.cityList, ally) table.sort(NDB.cityList) if not NDB_Exists(ally) then NDB_Acquire(ally) end
end
end setTriggerStayOpen("city members", 0) saveTableToJSON(NDB.cityList, "cityallylist")

enableTrigger("Crime Catcher")
enableTrigger("Crime Stopper")
IHateMathSoIWroteThis = {fines = 0, term = 0, oldestDate = 10000, newestDate = 0 }

local date = matches[2] local name = matches[3] local crime = matches[4] local fine = matches[5] local term = matches[6]
IHateMathSoIWroteThis.fines = tonumber(IHateMathSoIWroteThis.fines) + tonumber(fine)
if tonumber(date) == IHateMathSoIWroteThis.newestDate then IHateMathSoIWroteThis.term = tonumber(IHateMathSoIWroteThis.term) + tonumber(term) else IHateMathSoIWroteThis.term = tonumber(term) end IHateMathSoIWroteThis.newestDate = tonumber(date)

Alias.script:
if not NDB then cecho("\n<red>Name database not currently loaded.") else parsingQW = true peopleOnline = {}
-- Match against your valid city list or default to "All" local requested = matches[2] and matches[2]:title() or "All" local validCities = {Ashtan=true, Eleusis=true, Hashan=true, Mhaldor=true, Cyrene=true, Targossas=true}
parsingCity = validCities[requested] and requested or "All"
sendGMCP("Comm.Channel.Players") NDB_GetOnline() end

local remove = {} local cat, num = matches[2], tonumber(matches[3])
for i,v in pairs(NDB.players) do if cat == "rank" then if v.xp_rank == nil or v.xp_rank == 0 or v.xp_rank > num then table.insert(remove, v.name) NDB.players[v.name] = nil end else if not v.level or v.level < num then table.insert(remove, v.name) NDB.players[v.name] = nil end end end table.sort(remove)
cecho("\nRemoved a total of <green>"..#remove.."<NavajoWhite> unranked people from the database:\n - ".. table.concat(remove, ", ")..".") send(" ")

local classList = {"Alchemist", "Apostate", "Bard", "Blademaster", "Depthswalker", "Dragon", "Druid", "Infernal", "Jester", "Magi", "Monk", "Occultist", "Paladin", "Pariah", "Priest", "Psion", "Runewarden", "Sentinel", "Serpent", "Shaman", "Sylvan","Unnamable"} local classes = { Alchemist = {}, Apostate = {}, Bard = {}, Blademaster = {}, Depthswalker = {}, Dragon = {}, Druid = {}, Infernal = {}, Jester = {}, Magi = {}, Monk = {}, Occultist = {}, Paladin = {}, Pariah = {}, Priest = {}, Psion = {}, Runewarden = {}, Sentinel = {}, Serpent = {}, Shaman = {}, Sylvan = {}, Unnamable = {}, }
for player, tab in pairs(NDB.players) do if tab.class and tab.class ~= "" then -- Force Title Case to match your 'classes' table keys local className = tab.class:title()
-- Check if the class actually exists in your table before inserting if classes[className] then table.insert(classes[className], player)
-- Handle the Dragon level check if tab.level >= 99 then table.insert(classes.Dragon, player) end else -- Optional: Log if a class is found that isn't in your list echo("\nUnknown class found: " .. className) end end end
cecho("Displaying class count of currently tracked players.") for _, class in ipairs(classList) do cecho("\n <DimGrey>[<NavajoWhite>"..class:title().."<DimGrey>]"..string.rep(" ", 13-string.len(class)).."- <NavajoWhite>"..#classes[class].." tracked people are "..class..".") end send(" ")

local classList = {"Alchemist", "Apostate", "Bard", "Blademaster", "Depthswalker", "Dragon", "Druid", "Infernal", "Jester", "Magi", "Monk", "Occultist", "Paladin", "Pariah", "Priest", "Psion", "Runewarden", "Sentinel", "Serpent", "Shaman", "Sylvan", "Unnamable"}
local classes = { Alchemist = {}, Apostate = {}, Bard = {}, Blademaster = {}, Depthswalker = {}, Dragon = {}, Druid = {}, Infernal = {}, Jester = {}, Magi = {}, Monk = {}, Occultist = {}, Paladin = {}, Pariah = {}, Priest = {}, Psion = {}, Runewarden = {}, Sentinel = {}, Serpent = {}, Shaman = {}, Sylvan = {}, Unnamable = {}, }
for player, tab in pairs(NDB.players) do -- Clean up the class name from NDB to match our table keys local className = tab.class:title()
if ((tab.city == matches[2]:title()) or (tab.city == "None" and matches[2]:title() == "Rogues")) and className ~= "" then -- Guard clause: only insert if the class exists in our 'classes' table if classes[className] then table.insert(classes[className], player)
if tab.level >= 99 then table.insert(classes.Dragon, player) end end end end
cecho("Displaying class count of currently tracked players in <"..NDB.highlighting[matches[2]:title()]..">"..matches[2]:title()..".")
for _, class in ipairs(classList) do if #classes[class] > 0 then cecho("\n <DimGrey>[<NavajoWhite>"..class:title().."<DimGrey>]"..string.rep(" ", 13-string.len(class)).."- <NavajoWhite>"..#classes[class].." tracked people are "..class..".") end end send(" ")

local cities = {"Ashtan", "Cyrene", "Eleusis", "Hashan", "Mhaldor", "Targossas",}
if not table.contains(cities, matches[2]:title()) and matches[2]:title() ~= "None" then cecho("Invalid city. Please choose from either "..table.concat(cities, ", ").." or none.") else local cl = (matches[2]:title() == "None" and NDB.highlighting.Rogues or NDB.highlighting[matches[2]:title()]) cecho("Displaying tracked people from <"..cl..">"..matches[2]:title()..":") local people = {} for i,v in pairs(NDB.players) do if v.city == matches[2]:title() then table.insert(people, v.name) end end table.sort(people)
cecho("\n <"..cl..">"..table.concat(people, ", ")..".") cecho("\n <NavajoWhite>Total: <green>"..#people..".") end

local target = matches[2]:title() lustlist = lustlist or {}
-- Find the position of the target in the table local index = table.index_of(lustlist, target)
if index then table.remove(lustlist, index) cecho("\n<red>[-] <white>" .. target .. " removed from Lust Whitelist.")
-- Save the change immediately saveTableToJSON(lustlist, "lustlist") else cecho("\n<yellow>[!] <white>" .. target .. " was not found in the Lust Whitelist.") end
send("") -- Keep the input line clean

tatQ = {}
inking = false
processTattoos()

charges = {}
tattoos = {}
-- Ensure the table has all possible keys so the menu can show them
initializeTattooSettings() 

send("tattoos")
tempTimer(.2, [[expandAlias('dtats')]])

