------------------------------------------------------------------------------- -- 🛡️ INSTANT BOOT-LEVEL OBJECT CACHES ------------------------------------------------------------------------------- GUI = GUI or {} inrift = inrift or {} pipes = pipes or {name = {}, refill = 3}
function initializeFileLoads() settings = settings or {} if settings.debug == nil then settings.debug = false end
local jsonDir = getMudletHomeDir() .. "/Achaean System/system/libs/json/" local ndbPath = getNDBPath()
-- 1. Ensure dkjson library is loaded if not dkjson then local dkjsonPath = getMudletHomeDir() .. "/Achaean System/system/libs/deps/dkjson.lua" if fileExists(dkjsonPath) then dkjson = dofile(dkjsonPath) debugEcho("green","Loaded dkjson library.") else debugEcho("red","dkjson.lua not found at: " .. dkjsonPath) return end end
-- 2. Ensure NDB directory and doesnotexist.json exist if not lfs.attributes(ndbPath, "mode") then lfs.mkdir(ndbPath) end
local doesNotExistFile = ndbPath .. "/doesnotexist.json" if not fileExists(doesNotExistFile) then jsonManager({ write = true, path = doesNotExistFile, data = {} }) debugEcho("green","Created missing doesnotexist.json") end
-- 3. Protective NDB Skeleton Init NDB = NDB or {} NDB.players = NDB.players or {} NDB.highlightNames = (NDB.highlightNames ~= nil) and NDB.highlightNames or true NDB.highlightPriority = NDB.highlightPriority or "city"
NDB.special = NDB.special or {} NDB.player_Notes = NDB.player_Notes or {} NDB.cityEnemies = NDB.cityEnemies or {} NDB.cityList = NDB.cityList or {} NDB.doesNotExist = NDB.doesNotExist or {} NDB.enemySettings = NDB.enemySettings or {bold = false, italics = false, underline = false}
NDB.highlighting = NDB.highlighting or { Ashtan = "purple", Cyrene = "CornflowerBlue", Eleusis = "green", Hashan = "orange", Mhaldor = "red", Targossas = "cyan", Enemies = "red", Rogues = "brown", Underworld = "brown", }
NDB.divine = { "Aegis", "Artemis", "Aurora", "Babel", "Deucalion", "Gaia", "Lorielan", "Lupus", "Neraeos", "Ourania", "Pandora", "Phaestus", "Prospero", "Sartan", "Scarlatti", "Twilight", "Valnurana", "Vastar", "Tlalaiad", "Romeo", "Juliet" }
-- 4. Load individual NDB player files if type(loadAllNDBPlayers) == "function" then loadAllNDBPlayers() else for file in lfs.dir(ndbPath) do if file:match("%.json$") and file ~= "doesnotexist.json" and file ~= "Online.json" then local fullPath = ndbPath .. "/" .. file local data = jsonManager({safe = true, path = fullPath, fallback = {}}) if data and data.name then NDB.players[data.name:title()] = data end end end debugEcho("green","✔ Loaded all NDB player files from disk storage directories.") end
-- 5. Load 'Does Not Exist' list local dneData = jsonManager({safe = true, path = doesNotExistFile, fallback = {}}) NDB.doesNotExist = dneData or {}
-- 6. Load City Ally List safely local allyPath = jsonDir .. "cityallylist.json" if fileExists(allyPath) then local cityList = jsonManager({safe = true, path = allyPath, fallback = {}}) if type(cityList) == "table" then NDB.cityList = cityList debugEcho("green","Loaded cityallylist from JSON records.") end end
-- 7. Load City Enemy List safely local enemyPath = jsonDir .. "cityenemylist.json" if fileExists(enemyPath) then local cityEnemies = jsonManager({safe = true, path = enemyPath, fallback = {}}) if type(cityEnemies) == "table" then NDB.cityEnemies = cityEnemies debugEcho("green","Loaded cityenemylist from JSON records.") end end
-- 8. Load additional system data tables --if type(loadAllTablesFromJSON) == "function" then loadAllTablesFromJSON() --end
-- 9. Load Core System Dependencies local depsDir = getMudletHomeDir() .. "/Achaean System/system/libs/deps" if lfs.attributes(depsDir, "mode") == "directory" then local filesToLoad = {} for file in lfs.dir(depsDir) do if file:match("%.lua$") and file ~= "dkjson.lua" then table.insert(filesToLoad, file) end end table.sort(filesToLoad)
for _, file in ipairs(filesToLoad) do local success, err = pcall(dofile, depsDir .. "/" .. file) if not success then cecho("<red>Error loading dependency file (" .. file .. "): " .. err .. "\n") end end end
-- 10. ENGAGE HIGHLIGHT ENGINE if type(NDB_loadHighlights) == "function" then NDB_loadHighlights() debugEcho("green", "✔ Name database highlighting system activated and running.") end end
function initializeFileSaves() settings = settings or {} if not settings.systemLoaded then return end
local jsonDir = getMudletHomeDir() .. "/Achaean System/system/libs/json/" local ndbPath = getNDBPath()
-- 1. Essential Library Check if not dkjson then local dkjsonPath = getMudletHomeDir() .. "/Achaean System/system/libs/deps/dkjson.lua" if fileExists(dkjsonPath) then dkjson = dofile(dkjsonPath) else cecho("<red>Cannot save files: dkjson library file not found at dependency path.\n") return end end
-- 2. Directory Safety if not lfs.attributes(jsonDir, "mode") then lfs.mkdir(jsonDir) end if not lfs.attributes(ndbPath, "mode") then lfs.mkdir(ndbPath) end
-- 3. Save Per-Player NDB Data local savedCount = 0 if NDB and NDB.players and next(NDB.players) then for name, data in pairs(NDB.players) do if type(data) == "table" and name and name ~= "" then local safeName = name:title() local fullPath = ndbPath .. "/" .. safeName .. ".json"
jsonManager({ write = true, path = fullPath, data = data }) savedCount = savedCount + 1 end end debugEcho("green", string.format("✔ Successfully archived %d separate NDB player profiles.", savedCount)) end
-- 4. Save NDB "Does Not Exist" tracking file if NDB and NDB.doesNotExist then jsonManager({ write = true, path = ndbPath .. "/doesnotexist.json", data = NDB.doesNotExist }) end
-- 5. Execute Master Table Core Save if type(saveAllTablesAsJSON) == "function" then saveAllTablesAsJSON() else debugEcho("yellow","Note: saveAllTablesAsJSON() skipped (not defined).") end
debugEcho("green","✔ All system data safely synced to disk.") end
function systemOnDeath() if not settings.systemPaused then myaffs = {} send("stop") expandAlias("mstop") settings.systemPaused = true resetCuringList() LimbTrackerReset() cecho("\n<red>[BRAIN] We died. Disengaging.\n") if hunting then tempAreaList = {} huntloop = false hunting = false autohunting = false toggleHuntingMode("manual") end cecho("System has been <red>paused.\n") if settings.autoEmbrace then send("embrace death") end end end
function systemOnRespawn() local currentCuringSet = settings.curingset or "default" if settings.systemPaused then settings.systemPaused = false cecho("\nSystem has been " .. (settings.systemPaused and "<red>paused." or "<green>unpaused.")) myaffs = {} fortify:reset() remedy:reset() resetSelfPrecache() resetVitals() resetActiveDefenses() send("renounce grace") send("curingset switch " .. currentCuringSet) end end
------------------------------------------------------------------------------- -- 🏁 SYSTEM LOGIN EVENT ROUTINE ------------------------------------------------------------------------------- function systemLogin() SAVE_ALREADY_BACKED_UP = false BACKUP_RETENTION_DAYS = BACKUP_RETENTION_DAYS or 1
-- Reset volatile timer tracking markers (These should reset on every login) balance_start_time = 0 equilibrium_start_time = 0 health_start_time = 0 mana_start_time = 0 herb_start_time = 0 focus_start_time = 0 tree_start_time = 0 smoke_start_time = 0 salve_start_time = 0 shrugging_start_time = 0 stunned_start_time = 0
-- Initialize base objects safely pingCalculation = pingCalculation or {} NDB = NDB or {} inv = inv or {} inv_room = inv_room or {} roomstufflist = roomstufflist or {} jane = jane or {target = {}}
-- Reset active state flags hunting = false autohunting = false partysize = 1
-- TRACKING VECTORS (Preserve existing data if present) areaIgnoreList = areaIgnoreList or {} targetMasterList = targetMasterList or {} huntSettingsData = huntSettingsData or {} extermlist = extermlist or {} allylist = allylist or {} enemylist = enemylist or {} afflictions = afflictions or {} curinglist = curinglist or {} myaffs = myaffs or {} sentPriorityCommands = sentPriorityCommands or {} defenses = defenses or {} mydefs = mydefs or {} pipes_to_light = pipes_to_light or {} lustlist = lustlist or {} predictions = predictions or {} limbdamage = limbdamage or {} slainPlayers = slainPlayers or {} personalBalanceStartTimes = personalBalanceStartTimes or {} enemyBalanceStartTimes = enemyBalanceStartTimes or {}
-- Preserve pipeline or reset to default structure if nil pipeline = pipeline or {defenses = {}, afflictions = {}} lastPipelineCleanup = lastPipelineCleanup or 0
-- Volatile trackers tattoos = tattoos or { mindseye = {artefact = true, inked = true}, boar = {artefact = true, inked = true}, tree = {artefact = true, inked = true}, feather = {artefact = false, inked = false}, megalith = {artefact = false, inked = false}, cloak = {artefact = false, inked = false}, brazier = {artefact = false, inked = false}, tentacle = {artefact = false, inked = false}, web = {artefact = false, inked = false}, bell = {artefact = false, inked = false}, prism = {artefact = false, inked = false}, shield = {artefact = false, inked = false}, firefly = {artefact = false, inked = false}, moss = {artefact = false, inked = false}, hammer = {artefact = false, inked = false}, crystal = {artefact = false, inked = false}, moon = {artefact = false, inked = false}, starburst = {artefact = false, inked = false}, hourglass = {artefact = false, inked = false}, ox = {artefact = false, inked = false}, chameleon = {artefact = false, inked = false}, talon = {artefact = false, inked = false} }
LimbTracker = LimbTracker or {} LimbTracker.percentages = LimbTracker.percentages or { ["head"] = 0, ["torso"] = 0, ["left arm"] = 0, ["right arm"] = 0, ["left leg"] = 0, ["right leg"] = 0 } LimbTracker.data = LimbTracker.data or { ["head"] = 0, ["torso"] = 0, ["left arm"] = 0, ["right arm"] = 0, ["left leg"] = 0, ["right leg"] = 0 }
interpolationState = interpolationState or {health = false, mana = false, ep = false, wp = false, rank = false} end
-- Failsafe save on system kick function systemExit() if settings and settings.systemLoaded then settings.systemLoaded = false resetActiveDefenses() initializeFileSaves() if GUI and GUI.scorewindow then GUI.scorewindow:save() end if GUI and GUI.mapwindow then GUI.mapwindow:save() end if GUI and GUI.chatwindow then GUI.chatwindow:save() end if GUI and GUI.roomwindow then GUI.roomwindow:save() end if GUI and GUI.affwindow then GUI.affwindow:save() end if GUI and GUI.datawindow then GUI.datawindow:save() end saveTableToJSON(settings, "settings") end end
-- On manual logout function systemLogout() if settings and settings.systemLoaded then settings.systemLoaded = false resetActiveDefenses() initializeFileSaves() if GUI and GUI.scorewindow then GUI.scorewindow:save() end if GUI and GUI.mapwindow then GUI.mapwindow:save() end if GUI and GUI.chatwindow then GUI.chatwindow:save() end if GUI and GUI.roomwindow then GUI.roomwindow:save() end if GUI and GUI.affwindow then GUI.affwindow:save() end if GUI and GUI.datawindow then GUI.datawindow:save() end saveTableToJSON(settings, "settings") end end
function loadGMCPIRE() gmcp.IRE = gmcp.IRE or {} gmcp.IRE.Target = gmcp.IRE.Target or {} gmcp.IRE.Target.Info = gmcp.IRE.Target.Info or {} gmcp.IRE.Target.Info.hpperc = "-1"
sendGMCP("Char.Items.Inv") sendGMCP("IRE.Rift.Request") sendGMCP("Comm.Channel.Players") sendGMCP([[Core.Supports.Add ["Comm.Channel 1"] ]]) sendGMCP('Core.Supports.Add ["IRE.Target 1"]') sendGMCP('Core.Supports.Add ["IRE.Time 1"]') sendGMCP('Core.Supports.Add ["IRE.Tasks 1"]') sendGMCP('Core.Supports.Add ["IRE.Misc 1"]') sendGMCP('Core.Supports.Add ["IRE.Display 1"]') sendGMCP('Core.Supports.Add ["IRE.Sound 1"]') if vitalsGMCP then vitalsGMCP() end end
------------------------------------------------------------------------------- -- 🏁 BOOT ROUTINE ------------------------------------------------------------------------------- -- 1. KILL EXISTING HANDLERS if guiInitHandlerID then killAnonymousEventHandler(guiInitHandlerID) end
-- 2. THIS HANDLER ONLY RUNS ONCE TO BOOT GUI AND DATA guiInitHandlerID = registerAnonymousEventHandler("sysLoadEvent", function() initializeFileLoads()
if not settings.systemInstalled then installSystem() else -- Initialize the UI and local Data immediately (No GMCP needed yet) systemLogin() initializeSettings() initializeGUIContainers() initializeGUIWindows() initializeGUIGauges()
-- Start the "GMCP Watcher" to wait for the game to be ready enableGmcpWatcher() end end)
-- 3. THIS FUNCTION WAITS FOR THE GAME TO ACTUALLY TALK TO US function enableGmcpWatcher() -- We register a one-time event that waits for the game to send vitals registerAnonymousEventHandler("gmcp.Char.Vitals", function() if settings.systemLoaded then return end -- Don't run twice
cecho("\n<green>[SYSTEM] GMCP active. Finalizing game-specific data...")
loadGMCPIRE() updateCharStats() updateActiveCureData() updateCurativeTable() updateDefensiveTable()
startGameFeedPolling()
send("inv reset") send("plist") send("date")
settings.systemLoaded = true cecho("\n<green>[SYSTEM] All systems ready.") end) end
function arenaEvent() systemOnRespawn() send("stop") expandAlias("mstop") end
function systemConnected() settings = settings or {} settings.systemLoaded = false
initializeFileLoads() systemLogin() end
-- Register core system event handlers cleanly registerAnonymousEventHandler("characterRespawn", systemOnRespawn) registerAnonymousEventHandler("sysExitEvent", systemExit) registerAnonymousEventHandler("sysDisconnectionEvent", systemLogout) registerAnonymousEventHandler("sysConnectionEvent", systemConnected)

