function updateActiveCureData()
-- 1. Grab class safely and immediately smash it to strict lowercase local rawClass = class or (gmcp and gmcp.Char and gmcp.Char.Status and gmcp.Char.Status.class) or "Unknown" local gmcpClass = tostring(rawClass):lower()
-- 2. Define the core data. All lookup keys must be strictly lowercase. local coreCures = { ["alchemist"] = {type = "salt", command = "educe salt", cooldown = "salt", requires = "salt", blockers = {"stupidity","sleeping"}}, ["apostate"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["bard"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["blademaster"] = {type = "fitness", command = "fitness", cooldown = "fitness", requires = "fitness", blockers = {"weariness","sleeping"}}, ["depthswalker"] = {type = "chrono", command = "chrono", cooldown = "chrono", requires = "chrono", blockers = {"recklessness","sleeping"}}, ["dragon"] = {type = "dragonheal", command = "dragonheal", cooldown = "dragonheal", requires = "dragonheal", blockers = {"weariness","recklessness","sleeping"}}, ["druid"] = {type = "panacea", command = "evoke panacea", cooldown = "panacea", requires = "panacea", blockers = {"weariness","sleeping"}}, ["infernal"] = {type = "fitness", command = "fitness", cooldown = "fitness", requires = "fitness", blockers = {"weariness","sleeping"}}, ["jester"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["magi"] = {type = "bloodboil", command = "cast bloodboil", cooldown = "bloodboil", requires = "bloodboil", blockers = {"brokenleftarm","brokenrightarm","sleeping"}}, ["monk"] = {type = "fitness", command = "fitness", cooldown = "fitness", requires = "fitness", blockers = {"paralysis","sleeping"}}, ["occultist"] = {type = "fool", command = "fling fool at me", cooldown = "fool", requires = "fool", blockers = {"paralysis","sleeping"}}, ["paladin"] = {type = "fitness", command = "fitness", cooldown = "fitness", requires = "fitness", blockers = {"weariness","sleeping"}}, ["pariah"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["priest"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["psion"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["runewarden"] = {type = "fitness", command = "fitness", cooldown = "fitness", requires = "fitness", blockers = {"weariness","sleeping"}}, ["sentinel"] = {type = "fitness", command = "fitness", cooldown = "fitness", requires = "fitness", blockers = {"weariness","sleeping"}}, ["serpent"] = {type = "shrugging", command = "shrugging", cooldown = "shrugging", requires = {"balance","shrugging"}, blockers = {"weariness","sleeping"}}, ["shaman"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["sylvan"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["unnamable"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}},
-- 🟢 CONSOLIDATED ELEMENTAL VARIANTS ["air elemental"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["water elemental"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["fire elemental"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, ["earth elemental"] = {type = "", command = "", cooldown = "", requires = "", blockers = {"sleeping"}}, }
-- Clear engine data table before rebuilding activeCureData = {}
-- Populate from our normalized data map for name, data in pairs(coreCures) do activeCureData[name] = data end
-- 3. Run Validation check against our lowercase baseline if not coreCures[gmcpClass] and gmcpClass ~= "unknown" then local displayClass = rawClass:title() or "Unknown"
cecho("\n<red>SYSTEM ALERT: <white>Class: [" .. displayClass .. "] <DarkSlateGrey> -- is <red>NOT <DarkSlateGrey>in the ActiveCure table.")
-- Create safe backup profile inside your engine tracking array activeCureData[gmcpClass] = { type = "none", command = "", cooldown = "none", requires = "none", blockers = {"sleeping"} }
cecho("\n<red>!!! <DarkSlateGrey>Temporary dummy entry of <white>[" .. displayClass .. "] <DarkSlateGrey>created so system doesnt crash! ") end end

function NDB_Install() -- Initialize the global container safely without obliterating existing data NDB = NDB or {}
-- Preserve or set foundational attributes safely NDB.installed = true NDB.highlightNames = (NDB.highlightNames ~= nil) and NDB.highlightNames or true NDB.highlightPriority = NDB.highlightPriority or "city"
-- Populate memory containers if they aren't already initialized NDB.players = NDB.players or {} NDB.special = NDB.special or {} NDB.player_Notes = NDB.player_Notes or {} NDB.cityEnemies = NDB.cityEnemies or {} NDB.cityList = NDB.cityList or {} NDB.doesNotExist = NDB.doesNotExist or {}
-- Hardcoded base tables can be declared if missing NDB.highlighting = NDB.highlighting or { Ashtan = "purple", Cyrene = "CornflowerBlue", Eleusis = "green", Hashan = "orange", Mhaldor = "red", Targossas = "cyan", Enemies = "red", Rogues = "DarkSlateGrey", Underworld = "brown", }
NDB.enemySettings = NDB.enemySettings or {bold = false, italics = false, underline = false}
NDB.divine = { "Aegis", "Artemis", "Aurora", "Babel", "Deucalion", "Gaia", "Lorielan", "Lupus", "Neraeos", "Ourania", "Pandora", "Phaestus", "Prospero", "Sartan", "Scarlatti", "Twilight", "Valnurana", "Vastar", "Tlalaiad", "Romeo", "Juliet" }
-- 🔄 FIX REDUNDANCY: Call your local file loader straight from the installer! loadAllNDBPlayers()
cecho("\n<green>Systems have been Installed and profiles populated from disk.\n") NDB_Unhighlight() end
function loadAllNDBPlayers() local path = getNDBPath() NDB = NDB or {}
-- FIXED: Changed from NDB.players = {} to ensuring it exists. -- This stops it from flashing empty if called multiple times. NDB.players = NDB.players or {}
if not lfs.attributes(path, "mode") then debugEcho("yellow","NDB directory not found, skipping player load.") return end
local loadedCount = 0
for file in lfs.dir(path) do if file:match("%.json$") and file ~= "doesnotexist.json" and file ~= "Online.json" then local fullPath = path .. "/" .. file
local data = jsonManager({ safe = true, path = fullPath, fallback = {} })
if data and data.name then NDB.players[data.name:title()] = data loadedCount = loadedCount + 1 end end end
debugEcho("green", string.format("✔ Loaded %d individual NDB player files.", loadedCount)) end

function initializeTabWindows()
  Adjustable = Adjustable or {}
  Adjustable.TabWindow =
  Adjustable.TabWindow or Geyser.Container:new({name = "AdjustableTabWindowClass"})
  -- Save a reference to our parent constructor
  Adjustable.TabWindow.parent = Geyser.Container
  -- Create table to put every Adjustable.TabWindow in it
  Adjustable.TabWindow.all = Adjustable.TabWindow.all or {}
  Adjustable.TabWindow.all_windows = Adjustable.TabWindow.all_windows or {}
  Adjustable.TabWindow.allTabs = Adjustable.TabWindow.allTabs or {}
end

ScriptGroup.script:
Adjustable = Adjustable or {}
Adjustable.TabWindow = Adjustable.TabWindow or Geyser.Container:new({name = "AdjustableTabWindowClass"})

-- Save a reference to our parent constructor
Adjustable.TabWindow.parent = Geyser.Container
-- Create table to put every Adjustable.TabWindow in it
Adjustable.TabWindow.all = Adjustable.TabWindow.all or {}
Adjustable.TabWindow.all_windows = Adjustable.TabWindow.all_windows or {}
Adjustable.TabWindow.allTabs = Adjustable.TabWindow.allTabs or {}

Script.script:
function Adjustable.TabWindow:new(cons, container)
  Geyser.HBox.organize = Geyser.HBox.organize or Geyser.HBox.reposition
  local me = self.parent:new(cons, container)
  cons = cons or {}
  setmetatable(me, self)
  self.__index = self
  me.type = "adjustabletabwindow"
  me.defaultDir = me.defaultDir or getMudletHomeDir() .. "/AdjustableTabWindow/"
  me.tabs = me.tabs or {}
  me.tabTxtColor = me.tabTxtColor or "white"
  me.tabPadding = me.tabPadding or 12

  -- Ensure default colors are black
  me.color1 = me.color1 or "black" -- Black background
  me.color2 = me.color2 or "black" -- Black background
  me.activeTabBGColor = me.activeTabBGColor or me.color1
  me.inactiveTabBGColor = me.inactiveTabBGColor or me.color2
  me.tabBarHeight = me.tabBarHeight or "35"
  me.gap = me.gap or 0

  -- Update styles to use black backgrounds
  me.footerStyle =
    me.footerStyle or
    [[
    background-color: ]] .. me.color1 .. [[;
    border: 2px solid white;
    border-bottom-left-radius: 10px;
    border-bottom-right-radius: 10px;
    ]]

  me.centerStyle =
    me.centerStyle or
    [[
    background-color: ]] .. me.color2 .. [[;
    border: 2px solid white;
    border-radius: 10px;
    margin: 5px;
    ]]

  me.inactiveTabStyle =
    me.inactiveTabStyle or
    [[QLabel::hover{
        background-color: ]] ..
    me.activeTabBGColor ..
    [[;
        color: ]] ..
    me.tabTxtColor ..
    [[;
        border: 2px solid white;
        border-top-left-radius: 10px;
        border-top-right-radius: 10px;
        margin-right: 1px;
        margin-left: 1px;
        qproperty-alignment: 'AlignVCenter';
    }
    QLabel::!hover{
        background-color: ]] ..
    me.inactiveTabBGColor ..
    [[;
        color: ]] ..
    me.tabTxtColor ..
    [[;
        border: 2px solid white;
        border-top-left-radius: 10px;
        border-top-right-radius: 10px;
        margin-right: 1px;
        margin-left: 1px;
        qproperty-alignment: 'AlignVCenter';
    }
    ]]

  me.activeTabStyle =
    me.activeTabStyle or
    [[
    background-color: ]] ..
    me.activeTabBGColor ..
    [[;
    color: ]] ..
    me.tabTxtColor ..
    [[;
    border: 2px solid white;
    border-top-left-radius: 10px;
    border-top-right-radius: 10px;
    margin-right: 1px;
    margin-left: 1px;
    qproperty-alignment: 'AlignVCenter';
    ]]

  me.overlayStyle =
    me.overlayStyle or [[
    background-color: rgba(0,0,0,0%);
    border: 2px solid white;
    ]]

  me.tabBarStyle = me.tabBarStyle or [[
    background-color: ]] .. me.color2 .. [[;
    border: 2px solid white;
    ]]

  me.tempWindowConf =
    me.tempWindowConf or
    {
      buttonsize = "12",
      buttonFontSize = "7",
      padding = 9,
      buttonstyle =
        [[
        QLabel{ border-radius: 4px; background-color: rgba(0,0,0,90%); }
        QLabel::hover{ background-color: rgba(30,30,30,50%); }
        ]],
      adjLabelstyle = [[
        background-color: black; 
        border: 2px solid white;
      ]],
    }

  me:createBaseContainers()
  me:createTabs()

  if me.tabBarColor then
    me:setTabBarColor(me.tabBarColor)
  else
    me.tabBarColor = "black"
  end

  local found = string.match(" " .. me.activeTabStyle, "(%scolor:).-(;)")
  if not (found) then
    me.activeTabFGColor = me.activeTabFGColor or me.tabTxtColor
  end
  found = string.match(" " .. me.inactiveTabStyle, "(%scolor:).-(;)")
  if not (found) then
    me.inactiveTabFGColor = me.inactiveTabFGColor or me.tabTxtColor
  end

  if me.activeTabFGColor then
    me:setActiveTabFGColor(me.activeTabFGColor)
  end
  if me.inactiveTabFGColor then
    me:setInactiveTabFGColor(me.inactiveTabFGColor)
  end

  me.current = me.current or me.tabs[#me.tabs]
  if me.tabs[1] then
    me:activateTab(me.tabs[1])
  end

  tempTimer(
    0,
    function()
      if me.tabs[1] then
        me[me.tabs[#me.tabs] .. "center"]:hide()
      end
    end
  )
  if not Adjustable.TabWindow.all[me.name] then
    Adjustable.TabWindow.all_windows[#Adjustable.TabWindow.all_windows + 1] = me.name
  end
  Adjustable.TabWindow.all[me.name] = me
  return me
end

function numberOfAffs()
  local dangerLimbs = {"brokenleftleg", "brokenrightleg", "brokenleftarm", "brokenrightarm"}
  local i = 0
  for _, v in pairs(dangerLimbs) do
    if table.contains(myaffs, v) then
      i = i + 1
    end
  end
  return i + affcount()
end
